import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFileSync,writeFileSync} from "node:fs";
import {join} from "node:path";
import {readEngine} from "../support/engine.mjs";

const [enginePath,output,root]=process.argv.slice(2);
assert.ok(enginePath&&output&&root);assert.match(process.env.RING3_ENGINE_SHA256??"",/^[a-f0-9]{64}$/);
const engine=readEngine(enginePath),SIZE=4364,PC=0x1000,SRC=0x5008,DST=0x6008;
assert.deepEqual(WebAssembly.Module.imports(engine.module),[]);
const hash=b=>createHash("sha256").update(b).digest("hex"),bank=Buffer.alloc(64,0xcc);
const blocks=[[0,[0xa7,0xeb,0]],[8,[0xaf,0xeb,0]],
  [16,[0xb8,0xff,0xff,0xff,0x7f,0xaf,0xb8,0,0,0,0x80,0xaf,0xeb,0]],
  [32,[0xa7,0xa7,0xeb,0]],[40,[0x90,0xa7,0xeb,0]],[48,[0x90,0xaf,0xeb,0]]];
for(const [at,b] of blocks)bank.set(b,at);
assert.deepEqual(bank,readFileSync(join(output,"dword-string-compare.x86")),"independent Rust/JS bank");
const paths=["engine/src/abi/arena.rs","engine/src/abi/memory_helper.rs","engine/src/cpu/x86/ir.rs",
  "engine/src/cpu/x86/decode/lower.rs","engine/src/cpu/x86/decode/profile.rs","engine/src/cpu/dbt/region.rs",
  "engine/src/cpu/dbt/wasm/integer.rs","engine/src/cpu/dbt/wasm/memory.rs",
  "engine/tests/cpu_dword_string_compare_wasm.rs","engine/tests/fixtures/p2-dword-string-compare/run.mjs","engine/tests/fixtures/support/engine.mjs"];
const sourcePins=()=>Object.fromEntries(paths.map(path=>{const b=readFileSync(join(root,path));return[path,{bytes:b.length,sha256:hash(b)}];}));
const sources=sourcePins(),frames=[],journal=[],modules=[],targets=[],lifecycle=[];
const counts={profiles:0,modules:0,cmpsd:0,scasd:0,mov32:0,jumps:0,prefix_nops:0,fault_calls:0,controls:0,generated_calls:0,retired:0};
writeFileSync(join(output,"engine.wasm"),engine.bytes,{flag:"wx"});
function record(magic,size,fields=[],version=1){const b=Buffer.alloc(size);b.write(magic);b.writeUInt16LE(version,4);b.writeUInt16LE(1,6);b.writeUInt32LE(size,8);fields.forEach((v,i)=>b.writeUInt32LE(v>>>0,16+i*4));return b;}
const state=c=>record("R3ST",56,[...c.registers,c.pc,c.flags]);
const exit=(reason,n,detail=0,address=0)=>record("R3EX",40,[reason,n,detail,address,detail?1:0,detail?4:0],2);
const helper=(value,detail=0,address=0)=>record("R3MH",40,[detail?1:0,detail?0:value,detail,detail?address:0,detail?1:0,detail?4:0]);
const words=values=>Buffer.concat(values.map(v=>{const b=Buffer.alloc(4);b.writeUInt32LE(v>>>0);return b;}));
function arena(ctx){return Buffer.from(new Uint8Array(ctx.memory.buffer,ctx.base,SIZE));}
function capture(ctx,label){const b=arena(ctx),row={profile:ctx.profile,label,offset:frames.length*SIZE,sha256:hash(b)};frames.push(b);return row;}
function cpu(ctx){const b=arena(ctx);return {registers:Array.from({length:8},(_,i)=>b.readUInt32LE(16+i*4)),pc:b.readUInt32LE(48),flags:b.readUInt32LE(52)};}
function input(ctx,offset,b,label){const before=capture(ctx,"before input "+label),old=arena(ctx);new Uint8Array(ctx.memory.buffer).set(b,ctx.base+offset);old.set(b,offset);assert.deepEqual(arena(ctx),old);journal.push({profile:ctx.profile,type:"input",offset,hex:b.toString("hex"),label,before,after:capture(ctx,"after input "+label)});}
function host(ctx,name,args,expectedHelper){const old=arena(ctx),before=capture(ctx,"before "+name);assert.equal(ctx.api[name](...args),0,name);if(expectedHelper)old.set(expectedHelper,100);assert.deepEqual(arena(ctx),old,"full host neutrality/declared helper "+name);journal.push({profile:ctx.profile,type:"host",name,args,before,after:capture(ctx,"after "+name)});}
function upload(ctx,address,bytes){input(ctx,140,bytes,"uploaded literal bytes");host(ctx,"upload",[address,bytes.length]);}
function read(ctx,address,value){host(ctx,"read32",[address],helper(value));assert.equal(arena(ctx).readUInt32LE(120),value,"live declared DWORD diagnostic");}
function seed(ctx,pc,flags,source=SRC,destination=DST,eax=0xa53c5a81){const c={registers:[eax>>>0,0xb1c2d378,0x34560f10,0x4567ff00,0x56789abc,0x6789abcd,source,destination],pc,flags};const b=Buffer.alloc(140);b.set(state(c));b.set(exit(3,0),56);b.set(helper(0xdecafbad),100);input(ctx,0,b,"explicit CPU seed");return c;}
function run(ctx,budget,label,next,reason=1,n=1,nextHelper,fault,status=0){const expected=arena(ctx),before=capture(ctx,"before generated "+label);if(status===0){expected.set(state(next));expected.set(exit(reason,n,fault?.detail,fault?.address),56);if(nextHelper)expected.set(nextHelper,100);}assert.equal(ctx.run(ctx.base,ctx.base+56,budget,ctx.base+96),status,label);assert.deepEqual(arena(ctx),expected,"full generated arena "+ctx.profile+"/"+label);counts.generated_calls++;counts.retired+=status===0?n:0;const row={profile:ctx.profile,type:"run",label,budget,status,reason,n,before,after:capture(ctx,"after generated "+label)};journal.push(row);return row;}
function subtraction(left,right){const a=BigInt(left>>>0),b=BigInt(right>>>0),r=BigInt.asUintN(32,a-b);let flags=2;if(a<b)flags|=1;let ones=0;for(let i=0;i<8;i++)ones+=Number((r>>BigInt(i))&1n);if(!(ones&1))flags|=4;if((a^b^r)&16n)flags|=16;if(!r)flags|=64;if(r&0x80000000n)flags|=128;if((a^b)&(a^r)&0x80000000n)flags|=2048;return flags;}
for(const [a,b,wanted] of [[0,0,0x46],[0,1,0x97],[0x7fffffff,0xffffffff,0x887],[0x80000000,1,0x816],[0x100,0,6]])assert.equal(subtraction(a,b),wanted,"literal six-flag anchors");
function compare(ctx,kind,left,right,label){const before=cpu(ctx),next={registers:[...before.registers],pc:(before.pc+1)>>>0,flags:subtraction(left,right)|(before.flags&0x400)},delta=before.flags&0x400?-4:4;if(kind==="cmpsd")next.registers[6]=(next.registers[6]+delta)>>>0;else assert.equal(before.registers[0],left,"current full EAX is left operand");next.registers[7]=(next.registers[7]+delta)>>>0;const row=run(ctx,1,label,next,1,1,helper(right));counts[kind]++;targets.push({profile:ctx.profile,kind,label,before:row.before,after:row.after});return next;}
function mov(ctx,value){const before=cpu(ctx),next={...before,registers:[...before.registers],pc:before.pc+5};next.registers[0]=value;run(ctx,1,"real MOV supplies current full EAX",next);counts.mov32++;}
function jump(ctx,pc){run(ctx,2,"JMP with spare budget reaches cold continuation",{...cpu(ctx),pc},3,1);counts.jumps++;}
function open(owner,entries){const instance=new WebAssembly.Instance(engine.module,{}),ctx={owner,entries,profile:owner+"/"+(entries?"entry":"explicit"),memory:instance.exports.memory,api:{}};for(const name of ["open","close","arena_ptr","map","unmap","protect","upload","read32","compile","compile_entries","compile_resident","compile_resident_entries","generation","module_ptr","module_len","guard","guard_resident"]){ctx.api[name]=instance.exports["ring3_abi_v1_"+name];assert.equal(typeof ctx.api[name],"function",name);}assert.equal(ctx.api.open(10,1,0x51525354),0);ctx.base=ctx.api.arena_ptr()>>>0;for(const address of [PC,0x5000,0x6000,0x7000,0xfffff000,0])host(ctx,"map",[address,1,address===PC?7:3]);upload(ctx,PC,bank);input(ctx,140,words(entries?blocks.map(([o])=>PC+o):blocks.flatMap(([o,b])=>[PC+o,b.length])),"six compiler entries/descriptors");let binding;if(owner==="replacement"){host(ctx,entries?"compile_entries":"compile",entries?[6,0]:[6]);binding={generation:ctx.api.generation(),pointer:ctx.api.module_ptr()>>>0,length:ctx.api.module_len()>>>0};}else{const old=arena(ctx),before=capture(ctx,"before resident compile");assert.equal(entries?ctx.api.compile_resident_entries(6,0):ctx.api.compile_resident(6),0);const b=arena(ctx);assert.equal(b.readUInt32LE(140),1);assert.equal(b.readUInt32LE(144),24);binding=Object.fromEntries(["low","high","pointer","length"].map((name,i)=>[name,b.readUInt32LE(148+i*4)]));assert.ok(binding.low&&binding.length);old.set(b.subarray(140,164),140);assert.deepEqual(b,old,"only declared resident receipt changes");journal.push({profile:ctx.profile,type:"host",name:"compile_resident",before,after:capture(ctx,"after resident compile")});}const bytes=Buffer.from(new Uint8Array(ctx.memory.buffer,binding.pointer,binding.length)),module=new WebAssembly.Module(bytes),names=[owner==="resident"?"guard_resident":"guard","read32"];assert.deepEqual(WebAssembly.Module.imports(module),[{module:"env",name:"memory",kind:"memory"},...names.map(name=>({module:"ring3",name,kind:"function"}))]);assert.deepEqual(WebAssembly.Module.exports(module),[{name:"run",kind:"function"}]);ctx.run=new WebAssembly.Instance(module,{env:{memory:ctx.memory},ring3:ctx.api}).exports.run;assert.equal(ctx.run.length,4);ctx.binding=binding;const file="module-"+modules.length+".wasm";writeFileSync(join(output,file),bytes,{flag:"wx"});modules.push({profile:ctx.profile,file,bytes:bytes.length,sha256:hash(bytes),imports:names,...binding});counts.profiles++;counts.modules++;return ctx;}

const PAIRS=[[0,0],[0,1],[1,0],[0x7fffffff,0xffffffff],[0x80000000,1],[0x10,1],[0xffffffff,1],[0x100,0]];
for(const owner of ["replacement","resident"])for(const entries of [false,true]){
  const ctx=open(owner,entries),fp=record("R3FP",128,[0x55aa027f,0x03ffffff,0xf1234567,0xfedcba98,0xe246f135]);fp.set(Buffer.from(Array.from({length:80},(_,i)=>(i*73+29)&255)),40);input(ctx,4236,fp,"opaque FP128 preserved by integer reads");
  for(const kind of ["cmpsd","scasd"])for(const flags of [2,0x402,0x8d7,0xcd7])for(const [left,right] of PAIRS){upload(ctx,SRC,words([left]));upload(ctx,DST,words([right]));const entry=PC+(kind==="cmpsd"?0:8);seed(ctx,entry,flags,kind==="cmpsd"?SRC:0xd008,DST,kind==="scasd"?left:0xa53c5a81);compare(ctx,kind,left,right,"numeric status-flag discriminator");read(ctx,SRC,left);read(ctx,DST,right);jump(ctx,entry+3);}
  for(const kind of ["cmpsd","scasd"])for(let bit=0;bit<32;bit++){const left=(2**bit)>>>0,right=1,flags=bit&1?0xcd7:0x8d7;upload(ctx,SRC,words([left]));upload(ctx,DST,words([right]));seed(ctx,PC+(kind==="cmpsd"?0:8),flags,SRC,DST,kind==="scasd"?left:0xa53c5a81);compare(ctx,kind,left,right,"full DWORD one-bit basis");}
  for(const kind of ["cmpsd","scasd"])for(const [source,destination,flags] of [[SRC+1,DST+1,2],[0x5ffe,0x6ffe,0xcd7],[0xfffffffc,0xfffffffc,2],[0,0,0xcd7]]){upload(ctx,source,words([0x80000100]));upload(ctx,destination,words([0x80000100]));seed(ctx,PC+(kind==="cmpsd"?0:8),flags,source,destination,0x80000100);compare(ctx,kind,0x80000100,0x80000100,"unaligned/cross-page/top valid span and pointer wrap");read(ctx,source,0x80000100);read(ctx,destination,0x80000100);}
  for(const flags of [2,0xcd7]){const delta=flags&0x400?-4:4;for(const [address,value] of [[SRC,0x7fffffff],[SRC+delta,0x80000000],[DST,0xffffffff],[DST+delta,1]])upload(ctx,address,words([value]));seed(ctx,PC+32,flags);compare(ctx,"cmpsd",0x7fffffff,0xffffffff,"first CMPSD uses old pointers");compare(ctx,"cmpsd",0x80000000,1,"second CMPSD uses current pointers");jump(ctx,PC+36);seed(ctx,PC+16,flags);mov(ctx,0x7fffffff);compare(ctx,"scasd",0x7fffffff,0xffffffff,"SCASD uses preceding real MOV full EAX");mov(ctx,0x80000000);compare(ctx,"scasd",0x80000000,1,"second SCASD uses current EAX without reseed");jump(ctx,PC+30);}
  const faults=[{kind:"cmpsd",side:"source",address:0x8008,detail:1},{kind:"cmpsd",side:"source",address:0x8008,detail:2},{kind:"cmpsd",side:"destination",address:0xa008,detail:1},{kind:"cmpsd",side:"destination",address:0xa008,detail:2},{kind:"scasd",side:"destination",address:0xa008,detail:1},{kind:"scasd",side:"destination",address:0xa008,detail:2},{kind:"cmpsd",side:"source",address:0x8ffe,detail:1,second:true},{kind:"cmpsd",side:"destination",address:0xaffe,detail:2,second:true},{kind:"scasd",side:"destination",address:0xaffe,detail:1,second:true}];
  for(const fault of faults){const page=fault.address&~0xfff,nextPage=page+0x1000,source=fault.side==="source"?fault.address:SRC,destination=fault.side==="destination"?fault.address:DST,value=fault.side==="source"?0x80000081:1;upload(ctx,SRC,words([0x80000081]));upload(ctx,DST,words([1]));if(fault.second){host(ctx,"map",[page,1,3]);upload(ctx,fault.address,words([value]).subarray(0,2));if(fault.detail===2){host(ctx,"map",[nextPage,1,3]);upload(ctx,nextPage,words([value]).subarray(2));host(ctx,"protect",[nextPage,1,2]);}}else if(fault.detail===2){host(ctx,"map",[page,1,3]);upload(ctx,fault.address,words([value]));host(ctx,"protect",[page,1,2]);}const at=fault.second?nextPage:fault.address,diagnostic={detail:fault.detail,address:at},entry=PC+(fault.kind==="cmpsd"?40:48),initial=seed(ctx,entry,0xcd7,source,destination,0x80000081),target={...initial,pc:entry+1};for(let attempt=0;attempt<2;attempt++){run(ctx,attempt?1:2,"faulting DWORD read retains target CPU after NOP",target,5,attempt?0:1,helper(0,fault.detail,at),diagnostic);counts.fault_calls++;if(!attempt)counts.prefix_nops++;}const repairPage=fault.second?nextPage:page;host(ctx,fault.detail===2?"protect":"map",[repairPage,1,3]);upload(ctx,fault.address,words([value]));let left=0x80000081,right=1;if(fault.kind==="cmpsd"&&fault.side==="destination"){upload(ctx,SRC,words([0x7fffffff]));upload(ctx,destination,words([0xffffffff]));left=0x7fffffff;right=0xffffffff;}assert.deepEqual(cpu(ctx),target,"host-only repair retains target CPU/EIP");compare(ctx,fault.kind,left,right,"same-CPU repair rereads current full RAM");read(ctx,source,left);read(ctx,destination,right);host(ctx,"unmap",[page,1]);if(fault.second)host(ctx,"unmap",[nextPage,1]);}
  const initial=seed(ctx,PC,0xcd7,0x8008,0xa008);for(let attempt=0;attempt<2;attempt++){run(ctx,1,"both absent: engine source-first ordering",initial,5,0,helper(0,1,0x8008),{detail:1,address:0x8008});counts.fault_calls++;}host(ctx,"map",[0x8000,1,3]);upload(ctx,0x8008,words([0x80000081]));for(let attempt=0;attempt<2;attempt++){run(ctx,1,"second DWORD fault cannot publish first result",initial,5,0,helper(0,1,0xa008),{detail:1,address:0xa008});counts.fault_calls++;}host(ctx,"map",[0xa000,1,3]);upload(ctx,0xa008,words([1]));assert.deepEqual(cpu(ctx),initial);compare(ctx,"cmpsd",0x80000081,1,"priority repair retains same CPU");host(ctx,"unmap",[0x8000,1]);host(ctx,"unmap",[0xa000,1]);
  for(const kind of ["cmpsd","scasd"])for(const side of kind==="cmpsd"?["source","destination"]:["destination"])for(const address of [0xfffffffd,0xfffffffe,0xffffffff]){upload(ctx,SRC,words([0x80000081]));upload(ctx,DST,words([1]));const source=side==="source"?address:SRC,destination=side==="destination"?address:DST,entry=PC+(kind==="cmpsd"?40:48),initial=seed(ctx,entry,0xcd7,source,destination,0x80000081),target={...initial,pc:entry+1};for(let attempt=0;attempt<2;attempt++){run(ctx,attempt?1:2,"full-width overflow before pointer wrap",target,5,attempt?0:1,helper(0,3,address),{detail:3,address});counts.fault_calls++;if(!attempt)counts.prefix_nops++;}}
  for(const entry of [PC,PC+8]){seed(ctx,entry,2,0xd008,0xe008);run(ctx,0,"budget0 avoids invalid reads",cpu(ctx),1,0);counts.controls++;input(ctx,96,words([1]),"explicit cancel");run(ctx,1,"cancel avoids invalid reads",cpu(ctx),2,0);counts.controls++;}
  input(ctx,96,words([0]),"restore cancel");input(ctx,0,Buffer.from([0]),"malformed state magic");run(ctx,0,"malformed State32 is neutral",cpu(ctx),1,0,undefined,undefined,2);counts.controls++;input(ctx,0,Buffer.from([0x52]),"restore State32 magic");input(ctx,52,words([0]),"invalid State32 FLAGS fixed bit");run(ctx,0,"invalid State32 FLAGS is neutral",cpu(ctx),1,0,undefined,undefined,2);counts.controls++;input(ctx,52,words([2]),"restore valid State32 FLAGS");
  upload(ctx,PC,Buffer.from([0xa7]));const held=Buffer.from(new Uint8Array(ctx.memory.buffer,ctx.binding.pointer,ctx.binding.length));run(ctx,0,"stale known owner retains full arena",cpu(ctx),1,0,undefined,undefined,4);counts.controls++;assert.deepEqual(Buffer.from(new Uint8Array(ctx.memory.buffer,ctx.binding.pointer,ctx.binding.length)),held,"live old allocation unchanged before getters/close");
  const beforeCloseFrame=frames.length-1;assert.equal(ctx.api.close(),0);lifecycle.push({profile:ctx.profile,type:"close",status:0,before_frame:beforeCloseFrame});
  assert.equal(ctx.run(ctx.base,ctx.base+56,0,ctx.base+96),5);counts.generated_calls++;counts.controls++;lifecycle.push({profile:ctx.profile,type:"closed-run",budget:0,status:5});
}
assert.deepEqual(counts,{profiles:4,modules:4,cmpsd:316,scasd:300,mov32:16,jumps:272,prefix_nops:72,fault_calls:160,controls:32,generated_calls:1096,retired:976});
assert.equal(targets.length,616);assert.equal(journal.filter(r=>r.type==="input").length,2048);assert.equal(journal.filter(r=>r.type==="host").length,2188);assert.equal(journal.filter(r=>r.type==="run").length,1092);assert.equal(frames.length,10656);assert.equal(lifecycle.length,8);
assert.deepEqual(sourcePins(),sources,"fixture sources unchanged");
const raw=Buffer.concat(frames);writeFileSync(join(output,"arenas.bin"),raw,{flag:"wx"});
const result={status:"ok",engine:{bytes:engine.bytes.length,sha256:engine.sha256},counts,source_pins:sources,modules,targets,journal,lifecycle,raw:{file:"arenas.bin",frames:frames.length,bytes:raw.length,sha256:hash(raw)},limits:["finite prefix-free DWORD CMPSD/SCASD; no REP/address16/segment/SIMD extension","full4364 saved input/host/1092 generated pairs and opaque FP128; live DWORD diagnostics are not a full RAM dump","ESI-first fault priority is engine contract, not universal hardware order","standalone refusal/unchanged helper adversarial corpus is native scope","only live original module allocation read; four closed calls assert raw status5 only, with no post-close arena observation/neutrality/lifetime claim","no performance/full-ISA claim"]};
writeFileSync(join(output,"result.json"),JSON.stringify(result,null,2),{flag:"wx"});console.log(JSON.stringify({status:result.status,...counts,raw_frames:frames.length,output}));
